// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Felsefe tarihi: İlk Çağ ve Orta Çağ (kolay).
const ozSocialscience11Kolay = <(String, String, List<String>, String)>[
  ('Hesiodos\'un "Theogonia" adlı şiirinde evrenin başlangıcında ilk ortaya çıkan varlık hangisidir?', 'Khaos (Kaos)', ['Eros, ilk doğan ve tek tanrı', 'Nyks (Gece)', 'Uranos (Gök)'], 'Hesiodos\'a göre her şeyden önce Khaos vardı; Gaia, Tartaros ve Eros ondan sonra gelir. Bu anlatı felsefe öncesi mitolojik köken açıklamasının örneğidir.'),
  ('Felsefenin MÖ 6. yüzyılda İyonya kentlerinde doğmasına zemin hazırlayan koşullar arasında aşağıdakilerden hangisi sayılır?', 'Ticaretle zenginleşen kentlerin farklı kültürlerle teması ve dogma dayatan bir rahip sınıfının bulunmaması', ['Tek bir kutsal kitabın bütün bilgiyi belirlediği ve rahip sınıfının düşünceyi yönettiği kapalı bir düzen', 'Merkezî bir imparatorluğun her görüşü denetleyip yasakladığı katı bir yönetim', 'Kentlerin dış dünyaya kapalı kalıp yalnız tarımla geçinen, değişimden uzak yaşaması'], 'İyonya ticaret limanlarıyla Mısır ve Mezopotamya\'nın bilgisine açıktı ve katı bir din kurumu düşünceyi sınırlamıyordu. Bu ortam doğaya mitlerden bağımsız bir akılla bakmayı kolaylaştırdı.'),
  ('Geleneksel anlatıya göre Thales\'in MÖ 585 yılındaki hangi doğa olayını önceden bildirdiği söylenir?', 'Güneş tutulmasını', ['Büyük bir depremi', 'Nil\'in taşkınını', 'Bir kuyruklu yıldızın geçişini'], 'Herodotos\'un aktardığına göre Thales, Lidya ile Med savaşı sırasında gerçekleşen güneş tutulmasını önceden kestirmiştir. Bu, doğa olaylarının düzenli ve öngörülebilir sayıldığını gösterir.'),
  ('Thales\'in mıknatısın demiri çekmesini açıklarken ileri sürdüğü görüş aşağıdakilerden hangisidir?', 'Mıknatısın bir ruhu vardır, bu yüzden hareket ettirebilir', ['Mıknatıs gökten düşen bir taştır ve ayrıca ateşin bir türüdür', 'Demir ile mıknatıs aynı elementin iki biçimidir', 'Çekim, havanın sıkışmasıyla ortaya çıkar'], 'Aristoteles\'in aktarımına göre Thales, mıknatısın demiri hareket ettirmesinden ötürü ona ruh atfetmiştir. Bu, canlılık ile madde arasında kesin bir ayrım yapılmadığını gösterir.'),
  ('Anaksimandros\'un canlıların kökeni hakkındaki görüşü aşağıdakilerden hangisidir?', 'İlk canlılar nemli ortamda oluşmuş, insan da balığa benzer canlılardan türemiştir', ['İlk canlılar gökten yağan tohumlardan oluşmuş, insan ise tanrılar tarafından ayrıca yaratılmıştır', 'Canlılar yalnızca ateşin soğumasıyla doğmuş, deniz canlıları ise sonradan ortaya çıkmıştır', 'Her tür, tanrılar tarafından ayrı ayrı ve bugünkü biçimleriyle bir anda yaratılmıştır'], 'Anaksimandros\'a atfedilen görüşe göre yaşam nemli ortamdan çıkmış, insan ise önce balık benzeri canlıların içinde gelişmiştir. Bu, doğaya dayalı ilk evrim benzeri spekülasyonlardan biridir.'),
  ('Pythagorasçılar bir telin uzunluğunu yarıya indirdiklerinde hangi müzik aralığını elde ettiklerini bulmuşlardır?', 'Oktav', ['Tam beşli', 'Tam dörtlü', 'Büyük üçlü'], 'Telin yarı uzunluğu 1:2 oranında bir oktav verir. Pythagorasçılar müzikteki uyumu sayı oranlarına bağlamış ve bunu evrenin sayısal düzenine genellemiştir.'),
  ('Pythagorasçılar için kutsal sayılan "tetraktys" nedir?', 'İlk dört sayının toplamı olan onu gösteren üçgen sıra dizilimi', ['Evrenin dört temel öğesini temsil eden dört kenarlı, değişmez bir kare şekil', 'Tanrılara adanmış dört mevsim şenliğinde okunan kutsal bir dörtlük', 'Akademia\'da okutulan dört dersi simgeleyen ve kapıya asılan bir amblem'], 'Tetraktys 1, 2, 3 ve 4 noktalık sıraların bir üçgen oluşturmasıdır; toplamı 10 eder. Pythagorasçılar bu diziliş üzerine yemin eder, ona kozmik bir anlam yüklerdi.'),
  ('Pythagorasçıların ruh anlayışında yer alan, ruhun bir bedenden ötekine geçtiğini öne süren öğreti hangisidir?', 'Metempsikoz (ruh göçü)', ['Anamnesis', 'Katarsis (arınma)', 'Ekpyrosis'], 'Pythagorasçılar ruhun ölümsüz olduğuna ve bedenler arasında göç ettiğine inanıyordu. Bu inanç, bazı yiyeceklere ve hayvan öldürmeye getirdikleri yasakların da dayanağıydı.'),
  ('Samos\'ta doğduğu bilinen Pythagoras, öğretisini yaymak için okulunu hangi kentte kurmuştur?', 'Kroton', ['Atina\'da', 'Efes', 'Sparta'], 'Pythagoras Samos\'tan ayrılıp Güney İtalya\'daki Yunan kolonisi Kroton\'a yerleşti ve okulunu burada kurdu. Bu yüzden Pythagorasçılık İtalya okulu olarak da anılır.'),
  ('Herakleitos\'un "Savaş her şeyin babasıdır" sözü neyi anlatır?', 'Zıtların çatışmasının oluşu ve uyumu ortaya çıkaran temel güç olduğunu', ['Devletlerin ancak savaşla kurulabileceğini ve savaşın bütün kentler için gerekli olduğunu', 'Savaşın ahlaken övülmesi gerektiğini ve savaşçıların kentin en bilge yurttaşları olduğunu', 'Barışın hiçbir zaman mümkün olmadığını ve her toplumun mutlaka yıkıma uğrayacağını'], 'Herakleitos\'a göre zıtlar arasındaki gerilim ve çatışma (polemos) evrendeki hareketi ve uyumu doğurur. Söz, savaşı övmekten çok doğadaki zıtlık ilkesine işaret eder.'),
  ('Herakleitos\'a "karanlık" (skoteinos) lakabının verilmesinin nedeni nedir?', 'Sözlerinin kısa, bilmece benzeri ve yoruma açık olması', ['Yeraltında karanlık bir mağarada yaşaması ve ışıktan kaçınması', 'Gözlerinin görmemesi ve düşüncelerini başkalarına dikte ettirmesi', 'Öğretisini gizli bir topluluğa saklayıp kimseye yazılı olarak aktarmaması'], 'Herakleitos kısa, çelişkili görünen ve çok anlamlı özdeyişlerle yazdığı için anlaşılması güç sayılmış ve bu lakapla anılmıştır. Efes\'te yaşamıştır.'),
  ('Herakleitos\'un "Yukarı giden yol ile aşağı giden yol aynıdır" sözü hangi düşüncesini örnekler?', 'Zıt görünen şeylerin aslında bir bütünün iki yüzü olduğunu', ['Evrenin kesin biçimde düz bir çizgi halinde ilerlediğini ve başlangıcı olmadığını', 'İyi ile kötünün birbirinden kesin biçimde ayrılmış, hiç karışmayan şeyler olduğunu', 'Hareketin ve değişimin gerçekte hiç var olmayan bir yanılsama olduğunu'], 'Aynı yol bir bakıştan yukarı, öteki bakıştan aşağıdır. Herakleitos zıtların birliği düşüncesini bu tür örneklerle anlatır.'),
  ('Parmenides\'in felsefesini aktardığı eserin biçimi ve içeriği aşağıdakilerden hangisidir?', '"Doğa Üzerine" adlı şiirde "hakikat yolu" ile "sanı yolu" ayrılır', ['Platon\'un yazdığı ve Parmenides\'in başlıca konuşmacı olduğu bir diyalog dizisi', 'Öğrencilerine ve Elea halkına yazdığı bir dizi felsefi ve siyasal mektup', 'Elea kentinin yasalarını ve yönetimini anlatan bir söylev'], 'Parmenides düşüncesini bir şiir biçiminde sundu. Şiirde akla dayanan hakikat yolu ile duyulara dayanan sanı yolu birbirinden ayrılır.'),
  ('Melissos, Parmenides\'ten ayrılarak varlığın hangi niteliğini savunmuştur?', 'Zaman ve uzamda sınırsız olduğunu', ['Sınırlı bir küre biçiminde olduğunu', 'Sürekli değiştiğini', 'Dört öğeden oluştuğunu'], 'Samoslu Melissos varlığın sonsuz olduğunu, bir başlangıcı ve sınırı bulunmadığını öne sürdü. Parmenides ise varlığı sınırlı bir küreye benzetmişti.'),
  ('Aristoteles\'in aktarımına göre diyalektiğin, yani karşıt görüşün öncüllerinden yola çıkarak akıl yürütme sanatının kurucusu sayılan Sokrates öncesi filozof kimdir?', 'Elealı Zenon', ['Herakleitos', 'Protagoras', 'Anaksimandros'], 'Aristoteles, kaynaklara göre diyalektiği Zenon\'un başlattığını söylemiştir. Zenon karşıtının kabul ettiği öncüllerden çelişkili sonuçlar çıkararak onu çürütürdü.'),
  ('Empedokles\'in dört öğeye (toprak, su, hava, ateş) verdiği ad aşağıdakilerden hangisidir?', 'Kökler (rhizomata)', ['Tohumlar (spermata)', 'Homoiomeriler', 'Atomlar'], 'Empedokles dört öğeyi "kök" diye adlandırır. Bunlar yok olmaz, yalnızca karışıp ayrışır. Aristoteles sonradan bunlara "öğe" (stoikheia) demiştir.'),
  ('Anaksagoras\'ın Atina\'da yargılanmasına yol açan görüşü aşağıdakilerden hangisidir?', 'Güneşin tanrı değil kızgın bir taş kütlesi olduğu', ['Evrenin sonsuz sayıda tanrıdan oluştuğu ve tanrıların gökte yaşadığı', 'Ruhun beden öldükten sonra ateşe dönüştüğü', 'Kentin yasalarının doğaya aykırı olduğu'], 'Anaksagoras güneşi ateşli bir taş kütlesi saydığı için dinsizlikle suçlandı. Dostu Perikles\'in yardımıyla kentten ayrıldığı anlatılır.'),
  ('Demokritos\'un ahlak anlayışında en yüksek amaç hangisidir?', 'Ruhun ölçülü neşesi ve dinginliği', ['Bedensel hazların en üst düzeye çıkarılması ve zevk', 'Siyasal iktidarı ele geçirmek', 'Servet biriktirmek'], 'Demokritos mutluluğu bedensel hazlarda değil, ruhun dengesi ve neşesinde, aşırılıktan kaçınmakta gördü. Buna euthymia der.'),
  ('Aristoteles Sokrates öncesi doğa filozoflarını hangi adla anar?', 'Physiologoi', ['Sofistler, yani paralı öğretmenler', 'Eleatlar, yani Elea okulunun öğrencileri', 'Peripatetikler, yani Lykeion\'da gezinerek ders verenler'], 'Aristoteles bu düşünürlere doğa üzerine konuşanlar anlamında "physiologoi" der. Onlar evrenin ilk ilkesini doğada aradı.'),
  ('Yunanca "arkhe" sözcüğü Sokrates öncesi felsefede hangi anlamda kullanılır?', 'Her şeyin kendisinden çıktığı ve kendisine döndüğü ilk ilke', ['Şehir yöneticisinin taşıdığı, soyluluğu belirten ve miras kalan unvan', 'Bir savaş stratejisini tartışmak için kurulan düşünce deneyi', 'Gençlere bilgiyi ücretle aktaran gezgin öğretmen'], 'Arkhe, hem başlangıç hem de yönetici ilke anlamına gelir. Doğa filozofları evreni oluşturan ve açıklayan temel ilkeyi bu adla araştırdı.'),
  ('Sofist Prodikos\'a atfedilen "Herakles\'in yol ayrımı" öyküsünde Herakles neyi seçmek zorunda kalır?', 'Kolay haz yolu ile zahmetli erdem yolu arasında bir tercih', ['İki kent arasındaki bir savaşta tarafsız kalıp kalmamak konusunda bir seçim', 'İki tanrıça arasında bir güzellik yarışmasında hakem olmak ve ödül vermek', 'Hayat ile ölüm arasında bir uzlaşma sağlayıp insanlığı kurtarmak'], 'Prodikos bu öyküyle insanın hazzı mı yoksa erdemi mi izleyeceği ikilemini anlatır. Sofistlerin ahlak öğretisine yönelmelerinin bir örneğidir.'),
  ('Sofistlerin "nomos–physis" (yasa–doğa) ayrımını tartışmaları neyi gündeme getirmiştir?', 'Toplumsal kuralların doğal mı yoksa insan yapısı, değişebilir kurallar mı olduğunu', ['Evrenin sonlu mu yoksa sonsuz mu olduğunun gerçek bir kanıta dayanıp dayanmadığını', 'Ruhun beden dışında yaşayıp yaşamadığının ve ölümden sonra ne olacağının tartışmasını', 'Atomların bölünüp bölünemeyeceğinin ve boşluğun var olup olmadığının tartışmasını'], 'Nomos insanların koyduğu yasa ve gelenek, physis ise doğadır. Sofistler yasaların doğal bir temeli olup olmadığını sorarak ahlak ve siyaset tartışmasını başlattı.'),
  ('Sofist Gorgias\'ın "Helena\'nın Övgüsü" adlı konuşmasında asıl amacı nedir?', 'Sözün gücüyle olumsuz bir kişiyi bile aklayabileceğini göstermek', ['Troya Savaşı\'nın tarihsel nedenlerini ve savaşın ekonomik sonuçlarını sistematik biçimde açıklamak', 'Güzelliğin ideasını felsefi biçimde tanımlamak ve ruhun güzelliğe yükselişini anlatmak', 'Homeros\'un yazdıklarını düzeltmek ve onun öykülerini yanlış olduğu gerekçesiyle çürütmek'], 'Gorgias Helena\'yı suçsuz gösteren bir konuşma yazar. Amaç retoriğin ikna gücünü sergilemektir.'),
  ('Bir sofist, bir hukuk davasında aynı konuya hem lehte hem aleyhte konuşabilmeyi öğretmektedir. Bu yaklaşım sofistlerin hangi tutumunu yansıtır?', 'Doğrunun kişiden kişiye değiştiği; amacın doğruyu bulmaktan çok ikna etmek olduğu', ['Evrensel doğruya akıl yürütmeyle her zaman ulaşılabileceği ve her tartışmanın bir doğru sonucu olduğu', 'Bilginin kaynağının yalnız vahiy olduğu ve insanın bu konuda tartışmaması gerektiği', 'Yalnız duyuların güvenilir olduğu, aklın her zaman yanıldığı'], 'Sofistler mutlak hakikatin bilinemeyeceğini düşünür, ikna sanatına ağırlık verirdi. Bu yüzden her konuda iki karşıt savı savunabilmeyi öğretirlerdi.'),
  ('Sofistlerin Atina\'da gençlere ders verirken diğer filozoflardan ayrılan yönü hangisidir?', 'Öğretimi ücret karşılığı yapmaları', ['Okullarını bir tapınak içinde kurmaları', 'Hiç konuşmayıp yalnızca yazmaları', 'Yalnızca soylu ailelerin kızlarına ders vermeleri'], 'Sofistler gezgin öğretmenlerdi ve ders karşılığı ücret alırdı. Sokrates ve Platon bunu eleştirdi ve bilgiyi satmaktan söz ettiler.'),
  ('Aristophanes\'in "Bulutlar" komedisinde Sokrates nasıl gösterilir?', 'Gökyüzünü inceleyen ve zayıf savı güçlü gösteren bir düşünür olarak', ['Savaşta büyük kahramanlıklar gösteren, ordu yöneten ve kenti savunan bir komutan olarak', 'Kentin yasalarını yazan ve halk meclisinde konuşma yapan saygın bir yönetici olarak', 'Tanrılara adak adayıp tapınakta kurban kesen, geleneklere bağlı bir rahip olarak'], 'Aristophanes Sokrates\'i sepet içinde havada asılı, doğa ve söz oyunlarıyla uğraşan biri olarak alaya alır. Bu karikatür, sonraki yargılanmasının havasını hazırlamış sayılır.'),
  ('Sokrates\'in ölüm cezasını yerine getirmek için kendisine içirilen zehirli bitki hangisidir?', 'Baldıran', ['Adaçayı', 'Kantaron', 'Mandragora'], 'Atina\'da idamlar baldıran zehriyle yapılırdı; Sokrates de cezasını Phaidon\'da anlatıldığı gibi bu zehri içerek yerine getirdi.'),
  ('Sokrates\'in yargılandığı davada suçlayıcılar arasında aşağıdakilerden hangisi yer alır?', 'Melitos', ['Kallikles', 'Lysias', 'Gorgias'], 'Sokrates\'i Melitos, Anytos ve Lykon suçladı. Platon\'un "Savunma"sında Melitos\'un sorgulanması önemli bir bölümdür.'),
  ('"Sınanmamış bir yaşam yaşanmaya değmez" sözü Sokrates\'in neyi vurguladığını gösterir?', 'Kendini ve yaşamını sürekli sorgulamanın insan için vazgeçilmez olduğunu', ['Yaşamın yalnız bilimle anlam kazandığını', 'Hayatın hiçbir şekilde değerli olmadığını', 'Herkesin yaşamını yöneticilerin denetimine bırakması gerektiğini'], 'Platon\'un "Savunma"sında Sokrates, sorgulamayı bırakıp susmak yerine ölmeyi yeğleyeceğini söylerken bu sözü kullanır. Anlamlı yaşam, eleştirel sorgulamayla mümkündür.'),
  ('Sokrates\'in kendi yazılı eseri bırakmamış olması, onu öğrenmek bakımından neye yol açmıştır?', 'Düşüncelerinin Platon, Xenophon ve Aristophanes gibi başkalarının anlatımlarından öğrenilmesine', ['Eserlerinin yalnız Arapça kaynaklarda korunmuş ve Avrupa\'ya çok sonra ulaşmış olmasına', 'Düşüncelerinin tümüyle bilinmez kalmasına ve hiçbir öğrencisinin onu anmamasına', 'Platon\'un hiç diyalog yazmamasına ve Akademia\'yı kurmamasına'], 'Sokrates yazı yazmadı. Düşünceleri esas olarak Platon\'un diyalogları, Xenophon\'un anıları ve Aristophanes\'in komedileri aracılığıyla bilinir; bu da gerçek Sokrates sorusunu doğurur.'),
  ('Sokrates\'in ahlak felsefesinde sıkça yinelenen "Kendini bil" öğüdü ilk olarak nereye yazılıdır?', 'Delphoi\'deki Apollon Tapınağı\'na', ['Atina Akropolü\'ndeki Parthenon Tapınağı\'na', 'Olympia\'daki Zeus Tapınağı\'na', 'Milet\'teki Didyma\'ya'], '"Gnothi seauton" yazısı Delphoi\'deki Apollon Tapınağı\'nda bulunuyordu. Sokrates bu sözü insanın kendi sınırlarını ve bilgisizliğini bilmesi anlamında benimsedi.'),
  ('Aristoteles\'e göre Sokrates felsefeye hangi iki yöntemsel katkıyı yapmıştır?', 'Tümevarımsal kanıtlar ve genel tanımlar', ['Kıyas kuramı ve kategori listesi çıkarma', 'Deney yöntemi ve gözlem günlüğü', 'Matematiksel ispat ve diyagram'], 'Aristoteles, Sokrates\'in felsefeye iki şey kazandırdığını söyler: örneklerden hareketle tümevarım yoluna gitmesi ve şeylerin genel tanımını arama çabası.'),
  ('Platon\'un asıl adı olarak kaynaklarda geçen ve "Platon" lakabının geniş omuzlu anlamına geldiği söylenen ad nedir?', 'Aristokles', ['Aristarkhos', 'Aristippos', 'Aristofanes'], 'Antik kaynaklara göre Platon\'un gerçek adı Aristokles\'ti. "Platon" adı geniş omuzları nedeniyle verilen lakap olarak anlatılır.'),
  ('Platon\'un Akademia\'yı kurmasının tarihi olarak kabul edilen dönem aşağıdakilerden hangisidir?', 'Yaklaşık MÖ 387', ['Yaklaşık MÖ 470 civarında', 'Yaklaşık MÖ 300', 'Yaklaşık MÖ 200'], 'Platon, Sicilya gezilerinden sonra Atina\'ya dönüp yaklaşık MÖ 387\'de Akademia\'yı kurdu. Okul, adını yakındaki Akademos kutsal koruluğundan aldı.'),
  ('Platon\'un "Menon" diyaloğunda Sokrates, eğitimsiz köle çocuğa hangi konuda sorular sorarak bilginin doğuştan olduğunu göstermeye çalışır?', 'Bir karenin alanını iki katına çıkarma sorunu', ['Tanrıların soyağacı ve bunların insanların yaşamına etkisi hakkında', 'Savaş sırasında ordunun nasıl dizilmesi gerektiği', 'Müzik aralıklarının sayısal oranları ve telin uzunluğu'], 'Köle çocuk yönlendirici sorularla bir geometri sorununun çözümünü kendi kendine bulur. Sokrates bunu bilginin ruhta zaten bulunduğu, yani anımsamanın kanıtı olarak sunar.'),
  ('Platon\'un "Menon" diyaloğunda tartışılan temel soru aşağıdakilerden hangisidir?', 'Erdemin öğretilebilir bir şey olup olmadığı', ['Evrenin bir başlangıcının olup olmadığı sorunu', 'Devlet için en iyi yönetim biçimi', 'Hazzın iyi olup olmadığı'], 'Diyalog Menon\'un "Erdem öğretilebilir mi?" sorusuyla başlar. Tartışmada erdemin tanımı ve bilginin doğası da ele alınır.'),
  ('Platon\'un "Devlet" diyaloğundaki güneş benzetmesinde güneş hangi kavrama karşılık gelir?', 'İyi ideası', ['Bilgelik erdemi', 'Ruhun arzulu parçası', 'Mağaranın dışındaki ateş'], 'Güneş görünen dünyada nesneleri hem görünür kılar hem varlıklarını besler; İyi ideası da idealar dünyasında şeyleri hem bilinebilir kılar hem de varlıklarının kaynağıdır.'),
  ('Platon\'un "Devlet"inde koruyucu savaşçı sınıfın özgün erdemi hangisidir?', 'Cesaret', ['Bilgelik', 'Ölçülülük', 'Ticari beceri'], 'Üç sınıfın erdemleri farklıdır: yöneticilerde bilgelik, savaşçılarda cesaret, üreticilerde ise ölçülülük baskındır. Adalet bu üçü arasında uyum kurmaktır.'),
  ('Platon\'un koruyucu sınıf için önerdiği düzenin hangisi doğrudur?', 'Özel mülkiyet ve aile yoktur, mal ve çocuklar ortaktır', ['Her koruyucunun geniş toprağı ve kendi ailesi vardır, mülk bölüşülür', 'Koruyucular yalnızca tüccarlık yapar', 'Koruyucular yalnızca din adamlarından seçilir'], 'Platon yöneticilerin kişisel çıkara kapılmaması için koruyucu sınıfa özel mülkiyeti ve aileyi yasaklar. Böylece kentin tümünü bir aile gibi görmeleri amaçlanır.'),
  ('Platon\'un yönetim biçimlerinin bozulma sırasında "timokrasi"yi belirleyen temel değer nedir?', 'Onur ve zafer sevgisi', ['Zenginlik arzusu ve para sevgisi', 'Aşırı özgürlük', 'Bilgelik'], 'Timokrasi savaşçı soyluların yönetimidir ve onur ile üstünlük hırsı ağır basar. Sonra zenginlik sevgisiyle oligarşi, özgürlük aşırılığıyla demokrasi gelir.'),
  ('Platon\'un "Phaidros" diyaloğunda ruh hangi benzetmeyle anlatılır?', 'Bir arabacının yönettiği iki atlı bir araba', ['Mağaradaki zincirli mahkûmların gölgelere bakışı', 'Bir geminin dümencisi ve mürettebatı', 'Bir tohum ve onun ağacı'], 'Arabacı akılı, iki at ise biri soylu biri asi olmak üzere ruhun irade ve arzu yanlarını simgeler. Ruh, bu iki atın çekişmesi içinde hakikate yükselmeye çalışır.'),
  ('Platon\'un "Şölen" (Symposion) diyaloğunda Diotima\'nın anlattığı "aşk merdiveni"nin sonunda ulaşılan şey nedir?', 'Güzelliğin kendisi', ['Bedensel haz ve gençlik güzelliğinin sonsuz tadı', 'Siyasi iktidar', 'Evlilik'], 'Diotima aşkı tek bir güzel bedenden başlayarak güzel ruhlara, yasalara, bilgilere ve en sonunda güzelliğin kendisine yükselen bir yolculuk olarak anlatır.'),
  ('"Şölen"de Aristophanes\'in anlattığı mitte insanlar neden birbirini arar?', 'Tanrılar tarafından ikiye bölünen ilk insanlar eksik yarılarını arar', ['Tanrılar onları aşk tohumlarıyla cezalandırır', 'Her insan doğuştan tek bir eşe yazgılıdır', 'Aşk, yıldızların konumundan doğar'], 'Mitte bütün olan eski insanlar Zeus tarafından ikiye bölünmüştür. Aşk, kayıp bütünlüğü arama özlemidir.'),
  ('Platon\'un "Timaios"unda dört öğeyle ilişkilendirilen düzgün çokyüzlülerden küp hangi öğeye karşılık gelir?', 'Toprak', ['Ateş', 'Hava', 'Su'], 'Platon ateşi dört yüzlüye, havayı sekiz yüzlüye, suyu yirmi yüzlüye, toprağı küpe bağlar. Küpün kararlılığı toprağın durağan yapısına uygun görülür.'),
  ('Platon "Timaios"ta evreni nasıl tasvir eder?', 'Demiurgos tarafından idealara bakılarak yapılmış, ruh ve akıl taşıyan canlı bir varlık', ['Kendiliğinden oluşmuş cansız bir makine', 'Sonsuz bir ateşin soğumasıyla biçimlenen kütle', 'İlk insanların yarattığı bir düzen'], 'Timaios\'ta evren, demiurgosun düzenli bir modele bakarak yaptığı, bir dünya ruhuna sahip güzel ve canlı bir bütündür.'),
  ('Platon\'un kendi idealar kuramına yönelik "üçüncü adam" eleştirisi hangi diyalogda öne sürülür?', 'Parmenides', ['Phaidon diyaloğunda', 'Timaios', 'Devlet'], '"Parmenides" diyaloğunda yaşlı Parmenides genç Sokrates\'e, insanlar ile insan ideası arasındaki benzerliği açıklamak için üçüncü bir idea gerekeceğini, bunun da sonsuza gideceğini gösterir.'),
  ('Platon\'un "Laches" diyaloğunda tanımı aranan erdem hangisidir?', 'Cesaret', ['Adalet', 'Ölçülülük', 'Dindarlık'], 'Laches\'te generaller Laches ve Nikias ile Sokrates cesaretin ne olduğunu tartışır. Diyalog çözümsüz kalır.'),
  ('Platon felsefesinde "eidos" (idea) sözcüğünün sözlük anlamı nedir?', 'Görünüş, biçim', ['Sayı', 'Düşünce', 'Atom'], 'İdea ve eidos sözcükleri görmek fiilinden türemiştir ve görünüş, biçim anlamına gelir. Platon bunları şeylerin değişmez örnek biçimleri için kullanır.'),
  ('Platon\'un Akademia\'sında Platon\'dan sonra okul başkanlığını kim yürütmüştür?', 'Speusippos', ['Aristoteles', 'Theophrastos', 'Xenokrates ile Eudoxos birlikte'], 'Platon\'un yeğeni Speusippos ölümünden sonra okulu devraldı. Aristoteles Akademia\'da öğrenci olsa da başkan seçilmedi.'),
  ('Akademia\'nın "şüpheci dönemi"nde okulun başına geçen ve doğru bilgiye ulaşılamayacağını savunan filozof kimdir?', 'Arkesilaos', ['Speusippos', 'Platon', 'Epikuros'], 'Arkesilaos, Platon\'dan ayrılmadan Sokrates\'in bilgisizliğine dönerek hiçbir şeyin kesin bilinemeyeceğini savundu. Bu dönemi Orta Akademia diye anılır.'),
  ('Şüpheci Akademia\'nın Karneades\'i, kesin bilginin olanaksızlığına karşın nasıl bir ölçüt önermiştir?', 'Olasılık', ['Mutlak akıl, kesin bilgi anlamında', 'Vahiy', 'Mistik sezgi'], 'Karneades kesin bilgiye ulaşılamayacağını savunsa da eyleme yol göstermek için bir şeyin ne denli inandırıcı, yani olası olduğunu ölçüt kabul etti.'),
  ('Platon\'un "Euthyphron" diyaloğunda ele alınan temel konu aşağıdakilerden hangisidir?', 'Dindarlığın (kutsallığın) ne olduğu', ['Devlet yönetimi ve en iyi yönetim biçimi tartışması', 'Ruhun ölümsüzlüğü', 'Aşkın doğası'], 'Euthyphron, babasını dava etmek üzereyken Sokrates\'le karşılaşır ve tartışma kutsallığın tanımı üzerine kurulur. Diyalog sonuçsuz biter.'),
  ('Platon\'un "Kritias" ve "Timaios" diyaloglarında hangi efsanevi kent anlatılır?', 'Atlantis', ['Truva, Homeros\'un anlattığı', 'Elysion', 'Olympos'], 'Platon Atlantis\'i Atina\'nın eski bir rakibi olarak anlatır. Bu anlatı genellikle bir ahlaki alegori sayılır.'),
  ('Bir öğrenci, güzel bir heykelin, güzel bir atın ve güzel bir insanın ortak noktasının "güzelin kendisi" olduğunu söylüyor. Bu düşünce Platon\'un hangi görüşüne dayanır?', 'Duyulur güzel şeylerin, değişmez bir güzellik ideasına katıldığı', ['Güzelin yalnızca bireysel zevke bağlı olduğu', 'Güzelliğin yalnız sanat yapıtlarında bulunduğu', 'Güzelin toplum sözleşmesiyle belirlendiği'], 'Platon, güzel şeylerin güzellik ideasına katılarak güzel olduğunu söyler. Güzelliğin kendisi değişmeyen, duyularla değil akılla kavranan bir idedir.'),
  ('Aristoteles\'in doğduğu Stageira kenti hangi bölgededir ve babasının görevi neydi?', 'Kuzey Yunanistan\'da; Makedon kralının hekimiydi', ['Atina\'da; kentin arkhonu olan bir devlet yöneticisiydi', 'Sicilya\'da; bir zeytinyağı tüccarıydı', 'Milet\'te; tapınak rahibiydi'], 'Aristoteles Makedonya yakınındaki Stageira\'da doğdu. Babası Nikomakhos Makedon sarayında hekimlik yapmıştı ve bu geçmiş Aristoteles\'in doğa bilimlerine ilgisiyle ilişkilendirilir.'),
  ('Aristoteles, Akademia\'da yaklaşık kaç yıl öğrenci ve öğretmen olarak bulunmuştur?', 'Yaklaşık yirmi yıl', ['Yaklaşık iki yıl, kısa süreyle', 'Yaklaşık elli yıl', 'Yaklaşık beş yıl'], 'Aristoteles 17 yaşında Akademia\'ya girdi ve Platon\'un ölümüne kadar yaklaşık yirmi yıl orada kaldı. Daha sonra Atina\'dan ayrıldı.'),
  ('Aristoteles\'in Lykeion\'daki halefi olan ve bitkiler üzerine çalışmalarıyla tanınan öğrencisi kimdir?', 'Theophrastos', ['Speusippos', 'Arkesilaos', 'Xenokrates'], 'Theophrastos Aristoteles\'in ölümünden sonra Lykeion\'un başına geçti ve botanik ile karakter incelemeleri yazdı. Bu yüzden botaniğin kurucusu sayılır.'),
  ('Aristoteles\'in "Kategoriler" adlı eserinde on kategori sıralanır. Bunların arasında aşağıdakilerden hangisi yer almaz?', 'Neden', ['Töz', 'Nicelik', 'Zaman'], 'Aristoteles\'in kategorileri töz, nicelik, nitelik, ilişki, yer, zaman, durum, sahip olma, etkinlik ve edilgidir. Neden bunlardan biri değildir.'),
  ('Aristoteles\'e göre bir varlığın "hylemorfik" yapısı hangi iki ilkeden oluşur?', 'Madde ve form', ['Ruh ve beden', 'Zıtlar ve uyum', 'Atom ve boşluk'], 'Her somut varlık, belirsiz bir maddenin belli bir formla birleşmesidir. Tunç ve heykelin biçimi bu ilişkiye örnektir.'),
  ('Aristoteles dört nedenden "erek (final) neden"i nasıl örneklendirir?', 'Sağlığın, yürüyüşün amacı olması', ['Bronzun heykelin maddesi olması', 'Heykeltıraşın heykeli yapması', 'Heykelin biçiminin tasarımda bulunması'], 'Bir şeyin ne için olduğu erek nedendir. Yürümek sağlıklı olmak için yapılıyorsa sağlık yürüyüşün erek nedenidir.'),
  ('Aristoteles\'in ilk hareket ettiricinin etkinliği için kullandığı ifade hangisidir?', 'Düşüncenin düşüncesi', ['Evrensel ateş, bütün maddenin ilkesi', 'Sonsuz hareket', 'Mutlak irade'], 'Tanrı en yüce düşünceyle uğraşır; en yüce şey kendisi olduğundan düşüncesi kendi düşüncesidir. Bu ona özgü saf bir etkinliktir.'),
  ('Aristoteles\'in doğa anlayışında ağır bir taşın aşağıya, ateşin yukarıya gitmesi neyle açıklanır?', 'Her elementin kendi doğal yerine yönelmesiyle', ['Dünya\'nın çekim gücü ile gezegenlerin aralarındaki ortak itişi', 'Havanın sürekli itmesiyle', 'Tanrının her an müdahalesiyle'], 'Aristoteles\'e göre toprak aşağıya, ateş yukarıya yönelir; çünkü her element kendi doğal yerini arar. Bu açıklama erekbilimsel bir doğa anlayışını yansıtır.'),
  ('Aristoteles\'in kozmolojisinde Ay\'ın üstündeki gök cisimleri hangi maddeden yapılmıştır?', 'Eter (beşinci öz)', ['Ateş (yerin üstündeki öğe)', 'Hava', 'Su'], 'Aristoteles dört öğeyi yalnız Ay altı dünyada görür. Gök cisimlerini sonsuza kadar dairesel hareket eden, değişmeyen eterden yapılmış sayar.'),
  ('Aristoteles\'in evren modelinde gök cisimleri nasıl yerleştirilmiştir?', 'Dünya merkezde olacak biçimde iç içe geçmiş küreler halinde', ['Güneş merkezde olacak biçimde birbirine bağlı kristal küreler halinde', 'Dağınık ve hareketsiz', 'Bir düzlem üzerinde yan yana'], 'Aristoteles, Eudoxos ve Kallippos\'un kürelerden oluşan modelini geliştirerek Dünya merkezli, iç içe kürelerle çevrili sonlu bir evren anlayışı sundu.'),
  ('Aristoteles\'in biyolojide "canlıların kademesi" (scala naturae) anlayışına göre sıralama nasıldır?', 'Bitkilerden başlayıp hayvanlar yoluyla insana doğru artan bir karmaşıklık', ['Canlıların tümü eşit düzeydedir', 'İnsandan bitkiye azalan ilahi ışık', 'Canlılar tanrılar tarafından rastgele dağıtılmıştır'], 'Aristoteles canlıları ruhun yeteneklerine göre basamaklandırır. Bitkiler beslenir, hayvanlar duyar, insan ayrıca akıl yürütür.'),
  ('Aristoteles\'in "Ruh Üzerine" adlı eserinde ruh ile beden arasındaki ilişkiyi açıklayan görüş hangisidir?', 'Ruh, bedenin formudur', ['Ruh, bedenin hapishanesidir', 'Ruh, kandır', 'Ruh, madde değil hiçbir şey değildir'], 'Aristoteles ruhu canlı bedenin formu ve ilk entelekheisi sayar. Bu yüzden ruh beden olmadan var olmaz; tek istisna etkin akıl olabilir.'),
  ('Aristoteles etikte "ahlaki erdemler" ile "aklî (dianoetik) erdemler"i ayırır. Aşağıdakilerden hangisi aklî erdemdir?', 'Pratik bilgelik (phronesis)', ['Cesaret (ahlaki erdem, alışkanlıkla)', 'Cömertlik', 'Ölçülülük'], 'Aristoteles\'e göre cesaret, cömertlik, ölçülülük alışkanlıkla kazanılır; phronesis ve sophia ise öğretimle gelişen aklî erdemlerdir.'),
  ('Aristoteles\'e göre "phronesis" nedir?', 'Neyin iyi olduğunu ve belirli durumda nasıl davranılacağını kavrayan pratik bilgelik', ['Doğa olaylarını açıklama bilgisi', 'Retorik sanatı', 'Matematik ispatı yapma becerisi'], 'Phronesis, belirli durumlarda doğru olanı seçmeyi sağlayan aklî erdemdir. Ahlaki erdemler phronesis olmadan doğru biçimde işlemez.'),
  ('Aristoteles\'in dostluk anlayışında "tam (kusursuz) dostluk" hangisidir?', 'Karşılıklı erdeme dayanan dostluk', ['Yarar gözeten ve çıkar birliğine dayanan dostluk türü', 'Hazza dayanan dostluk', 'Siyasal çıkara dayanan dostluk'], 'Aristoteles dostluğu yarar, haz ve erdem üzerine kurulu olarak üçe ayırır. Yalnız erdeme dayalı olan kalıcı ve kusursuz dostluktur.'),
  ('Aristoteles\'e göre insana özgü en yüksek etkinlik hangisidir?', 'Teoria', ['Savaşmak, düşmana üstünlük kurmak', 'Servet edinmek', 'Siyasetle uğraşmak'], 'Aristoteles en üstün mutluluğu, insandaki en yüce yeteneğin yani aklın en değerli konuya yönelmesinde, yani seyir etkinliğinde görür.'),
  ('Aristoteles\'in "Poetika"da trajedinin amacı olarak gördüğü "katharsis" nedir?', 'Acıma ve korku duyguları aracılığıyla duyguların arınması', ['Seyircinin eğlenmesi ve oyuncuların toplumdan ödül kazanması', 'Oyuncuların ödüllendirilmesi', 'Toplumun ahlaki dersler alması'], 'Aristoteles\'e göre trajedi acıma ve korku uyandırır ve bu duyguların arınmasını sağlar. Bu terim ayrıca tıbbi arınma anlamına da gelir.'),
  ('Aristoteles trajedinin altı öğesinden hangisini en önemli sayar?', 'Olay örgüsü', ['Dekor ve sahne düzeni, görsel etki', 'Müzik', 'Konuşma biçimi'], 'Poetika\'ya göre trajedinin en önemli öğesi olay örgüsüdür; çünkü trajedi insanlar değil eylemin taklididir.'),
  ('Epikuros\'un Atina\'da kurduğu okulun adı olan "Bahçe" okulunu ayıran özellik hangisidir?', 'Kadınları ve köleleri de öğrenci olarak kabul etmesi', ['Yalnızca soylu erkeklere, yüksek ücret karşılığında ders vermesi ve kadınları kabul etmemesi', 'Bütün üyelerinin siyasete katılmak zorunda olması', 'Öğrencilerden yüksek ücret alması'], 'Epikuros\'un Bahçesi bir ev ve bahçede kurulu, dostluğa dayalı bir topluluktu; kadınlar ve köleler de aramızda yer alabiliyordu. Bu, çağın okulları arasında alışılmadık bir tutumdu.'),
  ('Epikuros hazları üç türe ayırır. "Doğal ama gereksiz" haza örnek hangisidir?', 'Lüks ve çeşitli yemekler', ['Susuzluğu gidermek', 'Barınak bulmak', 'Şan ve şöhret peşinde koşmak'], 'Epikuros\'a göre doğal ve gerekli hazlar (yemek, su, barınak) doyurulmalıdır. Lüks yemek gibi doğal ama gereksiz hazlar zorunlu değildir, şan ve şöhret gibi boş istekler ise kaçınılmalıdır.'),
  ('Epikuros "Gizlenerek yaşa" (lathe biosas) öğüdüyle neyi savunur?', 'Kamusal çekişmelerden uzak, sakin ve dostlarla geçen bir yaşamı', ['Siyasal iktidarı ele geçirmek için gizli örgütler kurup dostlarını yönetime yerleştirmeyi', 'Servetini başkalarından saklamayı', 'Düşüncelerini hiç yazmamayı'], 'Epikuros siyasal hırs ve ün kaygısının huzuru bozduğunu düşündüğü için kamusal yaşamdan çekilmeyi önerir.'),
  ('Epikuros\'un tanrılar hakkındaki görüşü hangisidir?', 'Tanrılar vardır ama mutlu ve ölümsüzdür, insan işlerine karışmaz', ['Tanrılar yalnızca insan hayal gücünün ürünüdür, hiçbir biçimde var değildirler ve insanlar onlardan korkmamalıdır', 'Tanrılar evreni her an yönetir ve insanları cezalandırır', 'Yalnız tek bir tanrı vardır ve dünyayı yaratmıştır'], 'Epikuros tanrıları mutlu ve kusursuz varlıklar sayar, ama evrenle ilgilenmediklerini söyler. Böylece insanların tanrı korkusundan kurtulması amaçlanır.'),
  ('Lucretius\'un "De Rerum Natura" adlı eseri neyi yapmıştır?', 'Epikurosçu atomcu doğa felsefesini Latince şiirle anlatmıştır', ['Stoa felsefesini Yunanca düzyazıyla özetleyip Roma\'daki okullarda ders kitabı olarak yaymıştır', 'Kıyas mantığını Latinceye aktarmıştır', 'Platon\'un diyaloglarını şiire dökmüştür'], 'Lucretius Epikuros\'un öğretisini onbeş bin kadar dize halinde Latince anlatan şiir yazdı. Eser, atomcu düşünceyi Roma dünyasına taşıdı.'),
  ('Stoa okulunun kurucusu Zenon hangi adada doğmuştur?', 'Kıbrıs\'ta', ['Sicilya\'da (Syrakusa), Platon\'un da ziyaret ettiği bir koloni kentinde', 'Samos\'ta', 'Rodos\'ta'], 'Zenon, Kıbrıs\'ın Kition kentinde doğdu. Atina\'da boyalı sütunlu galeride (Stoa Poikile) ders verdiği için bu ad kullanıldı.'),
  ('Stoacılara göre evrene düzen veren ve her şeye nüfuz eden tanrısal ilkenin adı nedir?', 'Logos', ['Apeiron', 'Nous poietikos', 'Atom'], 'Stoacılar evrenin tanrısal bir akılla yönetildiğini ve bu aklın (logos) doğayla, kaderle ve Tanrı ile özdeş olduğunu savunur.'),
  ('Stoacılara göre "bilge kişi" kaderle ilişkisini nasıl kurar?', 'Kaderin kaçınılmaz olduğunu bilip onu bilinçle kabul eder', ['Kaderi yenmek için sürekli savaşır ve tanrıları iknaya çalışır, böylece olayların akışını değiştirir', 'Kader diye bir şey olmadığını söyler', 'Kaderi değiştirmek için tanrılara yalvarır'], 'Stoacılar evrendeki her şeyin kader gereği olduğuna inanır. Özgürlük, kaderi değiştirmek değil onu akıllıca benimsemektir.'),
  ('Stoacıların "kozmopolitizm" anlayışı neyi savunur?', 'Bütün insanların aynı evrensel akıldan pay aldığı için dünya yurttaşı olduğunu', ['Yalnızca Yunanlıların uygar olduğunu, öteki halkların akıldan pay alamayacağı için yurttaşlık hakkı bulunmadığını', 'Her kentin kendi ayrı yasalarına sıkı sıkıya bağlı kalmasını', 'İnsanların ırklara göre sınıflandırılmasını'], 'Stoacılara göre logos her insanda bulunur; bu yüzden herkes tek bir evrensel kentin yurttaşıdır. Bu görüş insan eşitliği düşüncesinin erken biçimlerindendir.'),
  ('Frigya\'da köle olarak doğan ve sonradan özgürlüğüne kavuşarak felsefe öğreten Stoacı filozof kimdir?', 'Epiktetos', ['Seneca', 'Marcus Aurelius', 'Khrysippos'], 'Epiktetos köleliğinden sonra Roma\'da, sonra Nikopolis\'te ders verdi. Öğrencisi Arrianos onun derslerini "Diatribai" ve "Enkheiridion" olarak yazıya geçirdi.'),
  ('Marcus Aurelius\'un Stoacı düşünceleri not ettiği ve Yunanca yazdığı eser hangisidir?', 'Kendime Düşünceler', ['Devlet, Platon\'un ideal kenti anlatan ve filozof krallara yönetim öneren uzun diyalog', 'De Officiis', 'Enkheiridion'], 'Roma imparatoru Marcus Aurelius, seferlerde kendisine yazdığı notları Yunanca "Kendime" başlığıyla bıraktı; eser günümüzde Düşünceler olarak bilinir.'),
  ('Seneca\'nın felsefi ve siyasi yaşamında dikkat çeken olay hangisidir?', 'İmparator Nero\'nun öğretmeniydi ve sonunda onun buyruğuyla intihara zorlandı', ['Atina\'da bir okul kurup öğrencilerine ücretsiz ders verdi ve sonradan Nero\'ya karşı ayaklanma başlattı', 'İskender\'in danışmanı oldu', 'Hapiste zehirle idam edildi'], 'Seneca genç Nero\'nun hocası ve danışmanıydı; sonradan Nero\'nun buyruğuyla yaşamına son vermek zorunda kaldı.'),
  ('Cicero\'nun felsefe tarihindeki başlıca önemi aşağıdakilerden hangisidir?', 'Yunan felsefesini Latinceye aktarıp Latince felsefe terimleri üretmesi', ['Stoa okulunu Atina\'da kurup Latince yerine Yunanca yazmayı sürdürmesi ve Roma\'dan uzak durması', 'Atomculuk kuramını geliştirmesi', 'Skolastik yöntemi başlatması'], 'Roma\'nın büyük hatibi Cicero, Yunan felsefesini Latince yazılarla tanıttı ve birçok terimi Latinceleştirdi. Bu yüzden Roma ile sonraki Avrupa felsefesinin dilini hazırladı.'),
  ('Plotinos\'un "Enneadlar" adlı eserini sonradan düzenleyip yayımlayan öğrencisi kimdir?', 'Porphyrios', ['Proklos, Plotinos\'tan yüzyıllar sonra yaşamış bir Yeni Platoncu filozof', 'Iamblikhos', 'Damaskios'], 'Plotinos\'un derslerini ve yazılarını altı dokuzluk (Enneadlar) halinde derleyen Porphyrios, aynı zamanda Plotinos\'un yaşam öyküsünü de yazdı.'),
  ('İskenderiyeli Hypatia\'nın felsefe ve bilim tarihindeki yeri nedir?', 'Matematik ve Yeni Platoncu felsefe öğreten, MS 415\'te öldürülen kadın düşünür', ['Stoa okulunun kurucusu olup Kıbrıs\'tan Atina\'ya gelerek boyalı galeride öğretisini yaymış bir filozof', 'Aristoteles\'in öğrencisi', 'Epikuros\'un Bahçesi\'nin yöneticisi'], 'Hypatia, İskenderiye\'de matematik, astronomi ve felsefe dersleri verdi. Kentteki çatışmalar sırasında MS 415\'te öldürüldü.'),
  ('Plutarkhos hangi alanda Roma çağının önde gelen yazarlarındandır?', 'Hayat öyküleri ve ahlak yazılarıyla', ['Atomcu bir doğa şiiri yazmış, Epikuros\'un öğretisini şiirle anlatan Roma şairi olması', 'Mantık kuramı', 'Doğa bilimi deneyleri'], 'Plutarkhos "Paralel Yaşamlar" adlı eserinde Yunan ve Roma\'nın ünlü kişilerini karşılaştırır, "Moralia"da ise ahlak ve felsefe konularını işler.'),
  ('Claudius Galenos\'un Orta Çağ düşüncesine etkisi için hangisi doğrudur?', 'Hekimlik ve anatomi bilgisiyle yüzyıllar boyunca İslam ve Avrupa tıbbının otoritesi oldu', ['Atomculuğu reddedip ortaya koyduğu kıyas kuramıyla Orta Çağ\'da hukuk eğitimine yön vermesi ve devlet yönetmesi', 'Platon\'un Akademia\'sını yeniden kurdu', 'Hristiyan teolojisinin kurucusu oldu'], 'Galenos\'un tıp yazıları Arapçaya ve Latinceye çevrildi; İbn Sina da dahil olmak üzere Orta Çağ hekimlerinin başlıca kaynağıdır.'),
  ('Augustinus\'un "İtiraflar" adlı eserinin ana konusu nedir?', 'Kendi ruhsal arayışı ve Hristiyanlığa dönüşü', ['Roma tarihinin kronolojisini anlatan ve Roma\'nın yıkılışının nedenlerini sıralayan tarih kitabı', 'Aristoteles mantığının özeti', 'Atomcu fizik kuramının eleştirisi'], 'İtiraflar, Augustinus\'un gençlik yıllarındaki arayışını, Manihaizm\'den Hristiyanlığa geçişini ve Tanrı\'ya yönelişini anlatan otobiyografik bir yapıttır.'),
  ('Augustinus kötülüğü nasıl açıklar?', 'İyinin yokluğu veya eksikliği olarak', ['Tanrı\'nın eşiti ikinci bir ilke olarak', 'Maddenin doğal bir özelliği olarak', 'Yıldızların yarattığı kaçınılmaz bir etki olarak'], 'Augustinus Manihaizm\'in iki ilkesini reddedip kötülüğü varlığı olmayan, iyinin eksikliği (privatio boni) sayar. Kötülük, özgür iradenin kötüye kullanılmasının sonucudur.'),
  ('Augustinus\'un benimseyip sonradan eleştirdiği Manihaizm hangi öğretiye dayanır?', 'Evrenin iyi ve kötü iki eşit ilkenin savaşı olduğu görüşüne', ['Tek ve soyut bir Bir\'den her şeyin taşarak çıktığı Yeni Platoncu öğretiye', 'Yalnız atomların varlığı öğretisine', 'Tanrı\'nın evrenle özdeşliği öğretisine'], 'Manihaizm, İran kökenli Mani\'nin kurduğu ikici bir öğretidir. Augustinus gençliğinde yaklaşık dokuz yıl bu inanca bağlı kaldı.'),
  ('"Tanrı Devleti" adlı eserin yazılmasına yol açan tarihsel olay hangisidir?', 'Roma\'nın 410\'da Vizigotlar tarafından yağmalanması', ['Kudüs\'ün Romalılarca yıkılması ve Hristiyanların kentten sürülmesi', 'İstanbul\'un fethi', 'Atina\'nın Perslerce yakılması'], 'Roma\'nın 410\'da yağmalanması üzerine Hristiyanlar suçlanınca Augustinus, tarihi iki şehir arasındaki mücadele olarak yorumlayan bu eseri yazdı.'),
  ('Augustinus hangi şehrin piskoposu olarak görev yapmıştır?', 'Hippo', ['Roma, yaşamının son yıllarında ve Papa tarafından atanmış olarak', 'Atina', 'İskenderiye'], 'Tagaste\'de doğan Augustinus, yaşamının son otuz yılını Kuzey Afrika\'daki Hippo\'da piskopos olarak geçirdi.'),
  ('Boethius\'un idam edilmesinde ve "Felsefenin Tesellisi"nin yazılmasında hangi koşul etkilidir?', 'Gotların kralı Theodorik\'in onu haksız yere suçlayıp hapsetmesi', ['Romalıların onu Roma\'dan kovması ve Kilise\'nin kendisini aforoz etmesi', 'Kilisenin onu aforoz etmesi', 'İskender\'in ordusu'], 'Boethius yüksek devlet görevindeyken Theodorik\'e ihanetle suçlanıp hapse atıldı ve MS 524 dolaylarında idam edildi. Eserini hapiste yazdı.'),
  ('Boethius\'un Orta Çağ\'a bıraktığı önemli bir katkı hangisidir?', 'Aristoteles\'in mantık yapıtlarını Latinceye çevirmesi', ['Hristiyanlığa karşı yazılar yazıp Yunan çok tanrıcılığını yeniden canlandırması', 'Atomculuğu Latinceye aktarması', 'İlk üniversiteyi kurması'], 'Boethius Aristoteles\'in mantığını Latinceye aktardı. Bu çeviriler, Orta Çağ Batısı\'nın Aristoteles mantığını bilmesinin başlıca yolu oldu.'),
  ('Orta Çağ\'daki yedi liberal sanattan oluşan "trivium" aşağıdakilerden hangisidir?', 'Gramer, retorik, diyalektik', ['Aritmetik, geometri, müzik ve astronomi, yani sayıya dayalı dört alan', 'Astronomi, tıp, hukuk', 'Teoloji, hukuk, tıp'], 'Orta Çağ eğitimi önce trivium\'u (dil üç sanatı), sonra quadrivium\'u (aritmetik, geometri, müzik, astronomi) öğretirdi.'),
  ('Orta Çağ eğitiminde "quadrivium"a hangisi dahil değildir?', 'Retorik', ['Aritmetik', 'Geometri', 'Astronomi'], 'Quadrivium sayıya dayalı dört alandır: aritmetik, geometri, müzik ve astronomi. Retorik trivium içindedir.'),
  ('12. yüzyılda Aristoteles ve İbn Rüşd gibi yazarların Arapça kitaplarının Latinceye çevrilmesinde öne çıkan İspanyol kenti hangisidir?', 'Toledo', ['Kordoba', 'Granada', 'Sevilla'], 'Toledo Hristiyanların eline geçtikten sonra Gerard of Cremona gibi çevirmenlerin çalıştığı bir çeviri merkezi oldu. Bu çeviriler Latin Batı\'ya Aristoteles\'i yeniden kazandırdı.'),
  ('Orta Çağ\'ın ilk üniversiteleri arasında yer alan ve teoloji eğitimiyle öne çıkan kent hangisidir?', 'Paris', ['Londra', 'Roma', 'Atina'], 'Paris Üniversitesi 12. yüzyılın sonlarında şekillendi ve teoloji alanında en saygın kurum oldu. Bologna ise hukukta, Salerno tıpta öne çıkıyordu.'),
  ('Aquinas\'ın hocası olan ve "Doctor universalis" (evrensel doktor) olarak anılan düşünür kimdir?', 'Albertus Magnus', ['Bonaventura', 'Roger Bacon', 'Duns Scotus'], 'Albertus Magnus Köln\'de ders verdi, Aristoteles\'in doğa eserlerini şerh etti ve doğa bilimleri gözlemleriyle tanındı. Dominik tarikatındandı.'),
  ('Thomas Aquinas hangi tarikata mensuptur?', 'Dominikan (vaizler) tarikatı', ['Fransisken (yoksullar) tarikatı, Assisili Francesco\'nun kurduğu vaaz ve yoksulluk topluluğu', 'Benediktin tarikatı', 'Cizvit tarikatı'], 'Aquinas Dominikan tarikatına katıldı; ailesi karşı çıksa da bu yolu seçti. Dominikanlar öğretim ve vaazla uğraşan dilenci tarikatıydı.'),
  ('Aquinas\'a göre "doğal yasa"nın en temel ilkesi hangisidir?', 'İyiyi yap ve kötüden kaçın', ['Güçlü olan haklıdır', 'Herkes yalnızca kendi çıkarını gözetmelidir', 'Yasalar kralın isteğinden ibarettir'], 'Aquinas\'a göre akıl, insan doğasına yerleştirilmiş olan bu temel ilkeyi kavrar. Diğer ahlak kuralları bundan türetilir.'),
  ('Aquinas yasaları dört türe ayırır. Tanrı\'nın evreni yöneten ezeli aklına ne denir?', 'Ezeli yasa', ['Beşeri yasa, yani insanların kendi koyduğu ve değişebilen, geçici yasalar bütünü', 'İlahi yasa', 'Doğal yasa'], 'Ezeli yasa Tanrı\'nın evreni yöneten düzenidir. İnsanın aklıyla bu yasaya katılması doğal yasadır; beşeri yasa insan yapısı, ilahi yasa ise vahyedilmiş yasadır.'),
  ('Aquinas\'a göre kardinal erdemlere ek olarak "teolojik erdemler" hangileridir?', 'İman, umut ve sevgi', ['Cesaret, adalet ve ölçülülük', 'Bilgelik, cömertlik ve merhamet', 'Hayat, mülkiyet ve aile'], 'Dört kardinal erdem (sağduyu, adalet, cesaret, ölçülülük) akılla kazanılır; imanı, umudu ve sevgiyi Tanrı\'nın lütfu verir.'),
  ('Aquinas\'ın "beş yol"undan "hareket kanıtı"nın özü hangisidir?', 'Hareketlerin zinciri sonsuza gidemez, bu yüzden bir ilk hareket ettirici vardır', ['Hareket eden her şey kendi kendini hareket ettirir ve bir ilk hareket ettiriciye gerek duyulmaz, zincir sonsuza gider', 'Hareket edenin yalnızca insan olması', 'Hareketin tanrının iradesinden bağımsız oluşu'], 'Aquinas bu kanıtı Aristoteles\'ten alır: hareketlerin ilk bir hareket ettiriciye, yani Tanrı\'ya dayanması gerekir.'),
  ('Aquinas\'ın "beş yol" kanıtlarından hangisi, doğadaki cisimlerin bir amaca yöneldiğini gözlemlemeye dayanır?', 'Erek (düzen) kanıtı', ['Hareket kanıtı, yani her hareketin bir başka hareketle açıklanması', 'Etkin neden kanıtı', 'Derece kanıtı'], 'Bilinçsiz doğal cisimlerin bile amaca uygun işlemesi, onları yönlendiren bir akıllı varlığı gerektirir; Aquinas buna Tanrı der. Bu kanıt erek ya da düzen kanıtıdır.'),
  ('Aquinas\'a göre insan için nihai mutluluk nedir?', 'Tanrı\'yı doğrudan görmek', ['Servet biriktirip rahat bir hayat sürmek ve dünyevi zenginlikle huzura ulaşmak', 'Siyasi iktidar elde etmek', 'Bedensel hazlar'], 'Aquinas Aristoteles\'in mutluluğunu aşar; son mutluluğun ancak ölümden sonra Tanrı\'nın özünü görmekle gerçekleşeceğini savunur.'),
  ('Aquinas\'ın canonlaştırılması (aziz ilan edilmesi) hangi yüzyılda gerçekleşmiştir?', '14. yüzyılda', ['12. yüzyılda (1123), ölümünden hemen sonra, yaşarken', '16. yüzyılda', '18. yüzyılda'], 'Aquinas 1274\'te öldü. 1323\'te aziz ilan edildi ve onun öğretileri Katolik Kilisesi\'nde zamanla başlıca referanslardan biri oldu.'),
  ('Fransisken tarikatı kimin tarafından kurulmuştur?', 'Assisili Francesco', ['Domingo de Guzman, vaizler tarikatının İspanyol kurucusu', 'Benedictus', 'Anselmus'], 'Fransisken tarikatı yoksulluğu vaaz eden Assisili Francesco ile kuruldu. Dominikanlar ise Domingo de Guzman tarafından kuruldu.'),
  ('Abbasi halifesi Me\'mun döneminde Yunanca bilim ve felsefe eserlerinin Arapçaya çevrildiği Bağdat\'taki kurumun adı nedir?', 'Beytü\'l-Hikme', ['Nizamiye Medresesi', 'Dârülfünun', 'Ezher Camii'], 'Beytü\'l-Hikme (Bilgelik Evi) çeviri, kitap toplama ve araştırma merkezi olarak işlev gördü. Aristoteles ve Galenos gibi yazarların eserleri burada Arapçaya aktarıldı.'),
  ('Farabi\'nin doğduğu Farab (Otrar) bölgesi aşağıdaki hangi coğrafyadadır?', 'Orta Asya', ['Mısır\'da, Nil nehri ve İskenderiye çevresinde', 'Endülüs', 'Yemen'], 'Farabi, Orta Asya\'da Seyhun kıyısındaki Farab\'da doğdu ve eğitimine orada başladı. Daha sonra Bağdat\'a gitti.'),
  ('Farabi\'nin "İhsaü\'l-Ulum" adlı eseri neyi yapar?', 'Bilimleri sistemli biçimde sınıflandırıp tanıtır', ['Yalnızca dil bilgisini anlatır ve şiir türlerini sayar', 'Yalnızca gökbilimi anlatır', 'Yalnızca hukuku anlatır'], 'Eser, dil, mantık, matematik, fizik, metafizik ve siyaset bilimlerini sınıflandırır ve tanımlar. Bu eser Latinceye de çevrildi.'),
  ('Farabi\'nin sudur kuramında Tanrı\'dan ilk çıkan nedir?', 'İlk akıl', ['Maddenin kendisi, yani alt basamak', 'Ruh', 'Atom'], 'Farabi\'nin sudur öğretisine göre Tanrı\'dan birlik içinde ilk akıl, sonra on akıl ve gök küreleri taşar. Bu, Yeni Platoncu geleneğe dayanır.'),
  ('Farabi\'nin müzik alanındaki en önemli yapıtı hangisidir?', 'Kitabü\'l-Musika el-Kebir', ['Mukaddime', 'Şifa', 'Kanun'], 'Farabi bir müzisyen olarak da tanınır; müzik kuramı konusundaki büyük kitabı İslam dünyasının müzik düşüncesini derinden etkilemiştir.'),
  ('Farabi mantık alanında hangi katkısıyla öne çıkar?', 'Aristoteles\'in Organon\'unu şerhleyip Arap-İslam dünyasında mantığı yayması', ['Atomculuğu geliştirmesi', 'Fiziği kurması', 'Hukuk kitabı yazması'], 'Farabi Aristoteles\'in mantık yapıtlarına şerhler yazdı ve mantığı dil bilgisinden ayırarak ayrı bir bilim olarak sundu.'),
  ('İbn Sina\'nın doğduğu Afşana köyü hangi bölgededir?', 'Buhara yakınlarında', ['Bağdat yakınlarında, Dicle kıyısında', 'Kordoba yakınlarında', 'Kahire yakınlarında'], 'İbn Sina, Buhara yakınlarındaki Afşana\'da doğdu; çok genç yaşta tıp ve felsefede ün kazandı. Samanoğulları sarayında hekimlik yaptı.'),
  ('İbn Sina\'nın Farsça yazdığı felsefe kitabı hangisidir?', 'Danişname-i Alai', ['Kitabü\'ş-Şifa', 'El-Kanun fi\'t-Tıb', 'Kitabü\'n-Necat'], 'İbn Sina\'nın Arapça eserlerinin çoğunun yanında Farsça yazdığı "Danişname-i Alai" mantık, doğa bilimi ve metafizik bilgilerini özet biçimde sunar.'),
  ('İbn Sina\'nın "mümkün varlık" ve "zorunlu varlık" ayrımına dayanan Tanrı kanıtı hangi adla bilinir?', 'Sıddıkîn (doğruların) kanıtı', ['Mucize kanıtı, olağanüstü olaylardan', 'Düzen kanıtı', 'Ahlak kanıtı'], 'İbn Sina, mümkün varlıkların var olması için bir zorunlu varlığa ihtiyaç olduğunu, bu zorunlu varlığın da kendi varlığıyla kendinden olduğunu söyler.'),
  ('İbn Sina\'nın Latin Batı\'daki adı nedir?', 'Avicenna', ['Averroes', 'Avempace', 'Maimonides'], 'Avicenna adı İbn Sina\'nın Latince biçimidir. Averroes ise İbn Rüşd, Avempace İbn Bacce adıdır.'),
  ('İbn Sina\'ya yaygın olarak verilen "eş-Şeyhü\'r-Reis" unvanı neyi anlatır?', 'Bilginlerin başkanı, bilginlerin önde geleni', ['Askerî komutan, ordunun başı ve savaş yöneticisi', 'Din görevlisi', 'Ticaret loncası başkanı'], 'Bu unvan onun hem tıp hem felsefedeki üstünlüğünü ve devlet hizmetindeki konumunu belirtir.'),
  ('Gazali\'nin Bağdat\'taki başlıca öğretmenlik görevi hangi kurumda olmuştur?', 'Nizamiye Medresesi', ['Beytü\'l-Hikme\'de, çeviri evinde', 'Ezher', 'Kurtuba Camii'], 'Gazali Selçuklu veziri Nizamülmülk tarafından Bağdat Nizamiye Medresesi\'ne atandı ve burada büyük ün kazandı.'),
  ('Gazali\'nin Tehafütü\'l-Felasife\'de filozofları tekfir ettiği üç meseleden biri hangisidir?', 'Cesetlerin diriltilmesinin inkârı', ['Tanrı\'nın tek olduğunu söylemeleri', 'Namaz kılmaları', 'Mantık kullanmaları'], 'Gazali filozofları alemin ezeliliği, Tanrı\'nın tikelleri bilmemesi ve bedenlerin dirilişinin inkârı konularında tekfir eder. Diğer meselelerde ise yalnız yanlış bulur.'),
  ('Gazali\'ye "Hüccetü\'l-İslam" (İslam\'ın delili) unvanının verilmesi neden önemlidir?', 'Dinî bilimlerdeki otoritesini yansıtır', ['Siyasi bir görev olduğunu ve devlet yönetimini üstlendiğini', 'Askerî başarılarını gösterir', 'Bir ticaret ödülü olduğunu gösterir'], 'Bu unvan onun kelam, fıkıh ve tasavvuf alanlarındaki saygın konumunu ve İslam düşüncesindeki etkisini ifade eder.'),
  ('Gazali\'nin yaklaşık 1095\'te Bağdat\'tan ayrılıp tasavvufa yönelmesinin nedeni olarak anlatılan şey nedir?', 'Derin bir ruhsal bunalım ve kesin bilgiye ulaşma arayışı', ['Siyasi bir sürgün, halifenin buyruğuyla kentten çıkarılma', 'Ticaret amacı', 'Savaşa katılma isteği'], 'Gazali, öğretmenliğini bırakıp Şam, Kudüs ve Hicaz\'da zühd hayatı yaşadı. Yaşadığı kuşku ve bunalımı "El-Munkız" eserinde anlatır.'),
  ('Gazali\'nin "El-Munkız mine\'d-Dalal"da incelediği dört topluluktan biri aşağıdakilerden hangisidir?', 'Bâtıniler', ['Epikurosçular', 'Stoacılar', 'Kinikler'], 'Gazali kelamcıları, bâtınileri, filozofları ve sufileri inceler; sonunda sufilerin yolunda kesin bilgiye ulaşma imkânını bulur.'),
  ('İbn Rüşd\'ün Latin Batı\'da etkisiyle ortaya çıkan akım hangisidir?', 'Latin İbn Rüşdçülüğü', ['Skolastik gerçekçilik', 'Stoacılık', 'Epikurosçuluk'], 'Paris\'te Siger of Brabant gibi düşünürler İbn Rüşd\'ün Aristoteles yorumlarını benimsedi; bu akım Kilise\'nin tepkisini çekti.'),
  ('Sühreverdi\'nin kurduğu "İşrak felsefesi"nde temel kavram aşağıdakilerden hangisidir?', 'Nur', ['Atom ve boşluk öğretisi', 'Sayı', 'Töz'], 'İşrak "doğuş, aydınlanma" demektir. Sühreverdi\'ye göre bütün varlık, Nurlar Nuru\'ndan taşan ışık basamaklarıdır; madde ise karanlıktır.'),
  ('Muhyiddin İbn Arabi\'nin ünlü unvanı hangisidir?', 'Şeyh-i Ekber', ['Hüccetü\'l-İslam', 'Muallim-i Sani', 'Eş-Şeyhü\'r-Reis'], 'Endülüs\'te doğan İbn Arabi tasavvuf düşüncesinin en büyük sistemcisi sayıldığı için "en büyük şeyh" anlamına gelen Şeyh-i Ekber unvanıyla anılır.'),
  ('Mevlana\'nın hayatında dönüm noktası olarak anlatılan olay hangisidir?', 'Şems-i Tebrizi ile 1244\'te tanışması', ['Papa ile görüşmesi ve Haçlılara elçi olarak gitmesi', 'Moğol ordusuna katılması', 'Hacca gitmeye karar vermesi'], 'Mevlana, Şems ile karşılaştıktan sonra bir müderristen derin bir aşk ve şiir yaşamına yöneldi. Divan-ı Kebir\'i ona adadı.'),
  ('Mencius (Mengzi), insan doğasına ilişkin hangi görüşü savunur?', 'İnsan doğası özünde iyidir; kötülük kötü çevre ve eğitimden doğar', ['İnsan doğası özünde kötüdür', 'İnsan doğası boş bir levhadır', 'İnsan doğası tanrıların iradesiyle sabitlenmiştir'], 'Mencius, her insanda merhamet, utanç, saygı ve doğruyu yanlıştan ayırma tohumlarının bulunduğunu söyler. Eğitim bu tohumları geliştirir.'),
  ('Konfüçyüs\'ün öğretisinde "ren" (insanlık, erdem) kavramı ne anlama gelir?', 'Başkalarına karşı insancıl ve ilgili davranma erdemi', ['Devlet gücünü artırma ve orduyu güçlendirme becerisi, yönetim erdemi', 'Ataları anma töreni', 'Kehanet yeteneği'], 'Ren, Konfüçyüs\'ün en temel erdemidir; başkalarını sevmek ve onlara saygı göstermek anlamına gelir. "Kendin istemediğini başkasına yapma" ilkesiyle ifade edilir.'),
  ('Konfüçyüs\'ün diyaloglarının ve sözlerinin öğrencileri tarafından derlendiği kitap hangisidir?', 'Lunyu', ['Dao De Jing, Lao Zi\'ye ait kitap', 'Zhuangzi', 'Savaş Sanatı'], 'Lunyu, Konfüçyüs\'ün ölümünden sonra öğrencilerince bir araya getirilen söz ve konuşma derlemesidir.'),
  ('Konfüçyüsçülüğe göre beş temel ilişkiden biri aşağıdakilerden hangisidir?', 'Hükümdar–tebaa', ['Satıcı ile alıcı arasındaki ilişki', 'Rakip–rakip', 'Komşu–yabancı'], 'Beş ilişki hükümdar–tebaa, baba–oğul, koca–karı, ağabey–kardeş ve arkadaş–arkadaştır. Her ilişkinin karşılıklı yükümlülükleri vardır.'),
  ('Siddhartha Gautama\'nın ("Buda") yaşam öyküsünde onu sarayı terk etmeye iten olay nedir?', 'Yaşlılık, hastalık ve ölümle karşılaşıp acıyı fark etmesi', ['Savaşta yenilmesi ve babasının onu sarayından kovması', 'Tahttan indirilmesi', 'Bir tanrının emri'], 'Buda, genç bir prensken saray dışında yaşlı, hasta ve ölü bir insan görünce yaşamın acı yönünü fark etti ve hakikati aramak üzere ayrıldı.'),
  ('Upanişadlar hangi türden metinlerdir?', 'Vedaların felsefi ve mistik yorumlarını içeren metinler', ['Tıp kitapları ve hastalıkların tedavisine ilişkin kılavuzlar', 'Savaş el kitapları', 'Hukuk metinleri'], 'Upanişadlar Vedaların sonunda yer alan, brahman, atman ve kurtuluş üzerine düşünceler içeren metinlerdir ve "Vedanta" (Vedaların sonu) olarak da anılır.'),
  ('Antik felsefede "kosmos" (düzen, güzel düzen) sözcüğünü evren için ilk kullandığı aktarılan düşünür kimdir?', 'Pythagoras', ['Thales', 'Epikuros', 'Sokrates'], 'Geleneğe göre Pythagoras evreni düzenli ve uyumlu bir bütün olarak görüp "kosmos" adını vermiştir. Sözcük başlangıçta düzen ve süs anlamına gelirdi.'),
  ('Yunanca "physis" sözcüğü antik felsefede neyi anlatır?', 'Kendiliğinden oluşan ve büyüyen doğa', ['İnsan yapımı yasa ve geleneklerin toplamı, kentin yasası', 'Tanrıların iradesi', 'Sayılar arasındaki oran'], 'Physis, "doğa" kavramını, şeylerin kendi içlerinden büyüyen özünü anlatır. Nomos ise yasa ve gelenek karşılığıdır.'),
  ('Yunanca "aretê" sözcüğü hangi anlamı taşır?', 'Bir şeyin kendi işlevini en iyi yerine getirmesi', ['Zenginlik', 'Ün', 'Savaş'], 'Aretê hem ahlaki erdemi hem de bir şeyin özgün yeteneğini anlatır. Örneğin bıçağın keskinliği onun aretê\'sidir.'),
  ('Yunanca "psykhe" sözcüğü felsefede hangi anlamda kullanılır?', 'Canlıyı canlı yapan ilke', ['Zihinsel hastalık, akıl sağlığı bozukluğu', 'Kentin yöneticisi', 'Gök küresi'], 'Psykhe, bedeni canlı tutan can ve düşünme ilkesidir; psikoloji sözcüğü bu kökten gelir.'),
  ('"Eudaimonia" sözcüğü antik etikte hangi kavrama karşılık gelir?', 'İnsanın iyi ve gelişmiş yaşaması', ['Geçici haz ve anlık bedensel zevkler, ayrıca cömert yaşam', 'Zenginlik', 'Askerî başarı'], 'Eudaimonia, tek tek hazlardan çok erdemle yaşanan bütün bir yaşamın iyiliğini anlatır. Aristoteles, Stoa ve Epikuros bu terimi kullanır.'),
  ('Orta Çağ düşüncesinde "quaestio" ne anlama gelir?', 'Tartışmaya konu edilen felsefi ya da teolojik soru', ['Bir ayin düzeni, yani kilisede uygulanan düzenli ibadet töreni', 'Bir şehir', 'Bir kıyas türü'], 'Quaestio, skolastik yöntemde bir soruyu itirazlar ve yanıtlarla incelemeyi anlatır. Summa Theologiae bu biçimde kurulmuştur.'),
  ('Anlatılana göre Thales, Mısır\'da bir piramidin yüksekliğini nasıl ölçmüştür?', 'Kendi gölgesinin boyuna eşit olduğu anda piramidin gölgesini ölçerek', ['Piramidin tepesine ip bağlayarak', 'Piramidin taş sayısını sayarak', 'Güneşin açısını yıldızlardan hesaplayarak'], 'Gölge ile cismin boyunun orantılı olması, benzerlik düşüncesine dayanır. Bu anekdot Thales\'in geometriyi pratik bir sorunda kullandığını gösterir.'),
  ('Sokrates\'in askerî hizmet geçmişi hakkında doğru bilgi hangisidir?', 'Peloponnesos Savaşı sırasında hoplit olarak çeşitli seferlere katıldı', ['Hiç askerlik yapmadı', 'İskender\'in ordusunda görev yaptı', 'Perslere karşı komuta etti'], 'Platon\'un diyaloglarına göre Sokrates Potidaia ve Delion gibi savaşlara ağır silahlı piyade olarak katıldı ve cesaretiyle anıldı.'),
  ('Sokrates\'in eşi olarak anılan kadın hangisidir?', 'Ksantippe', ['Diotima', 'Aspasia', 'Hipparkhia'], 'Antik kaynaklarda Sokrates\'in eşi Ksantippe olarak geçer ve huysuzluğuyla anılır. Diotima ise Şölen\'de Sokrates\'in öğretmeni olarak anlatılan bir kadındır.'),
  ('Platon\'un "Phaidon"unda Sokrates\'in son sözü olarak aktarılan söz neyle ilgilidir?', 'Asklepios\'a bir horoz borcunun ödenmesi', ['Kentin yeni yasalarının onaylanması ve halkın uyarılması', 'Platon\'a bir mektup', 'Çocuklarının geleceği'], 'Sokrates zehri içtikten sonra Kriton\'a Asklepios\'a bir horoz borçlu olduklarını hatırlatır. Bu söz, ölümü bir iyileşme olarak görme biçiminde yorumlanır.'),
  ('Platon\'un "Şölen"inde Diotima\'ya göre Eros kimin çocuğudur?', 'Poros (çare) ile Penia (yoksulluk)\'nın', ['Zeus ile Hera\'nın, yani tanrıların kralı ve kraliçesinin', 'Ares ile Afrodit\'in', 'Kronos ile Gaia\'nın'], 'Diotima, Eros\'u bilge ile bilgisiz arasında, her zaman eksik olanı arayan bir daimon olarak betimler; felsefe de bu yüzden Eros\'a benzer.'),
  ('Platon\'a göre filozof yöneticinin eğitiminde diyalektiğe geçmeden önce hangi öğrenim gelir?', 'Matematik ve temel bilimler', ['Retorik', 'Askerî eğitim sonrası siyaset', 'Şiir sanatı'], 'Devlet\'te yöneticiler genç yaşta jimnastik ve müzik, ardından matematik ve bilimler, sonra diyalektik öğrenir. Böylece ruh duyulur dünyadan idealara yönelir.'),
  ('"Platonik cisimler" olarak anılan düzgün çokyüzlülerin sayısı kaçtır?', 'Beş', ['Üç', 'Yedi', 'On'], 'Dört yüzlü, küp, sekiz yüzlü, on iki yüzlü ve yirmi yüzlü olmak üzere yalnızca beş düzgün çokyüzlü vardır. Platon "Timaios"ta bunları evrenin yapısıyla ilişkilendirdi.'),
  ('Hellenistik dönemde yeryüzünün çevresini ilk kez ölçen kişi olarak bilinen Kyrene\'li bilgin kimdir?', 'Eratosthenes', ['Arkhimedes', 'Hipparkhos', 'Euklides'], 'Eratosthenes, İskenderiye ve Syene\'de öğle güneşinin açı farkını kullanarak Dünya\'nın çevresini hesapladı. Sonucu gerçeğe oldukça yakındır.'),
  ('Aristoteles\'e göre polis (kent-devlet) nasıl ortaya çıkar?', 'Ev topluluklarından köylere, köylerden polise doğal bir gelişimle', ['Bir sözleşmeyle ve zorla', 'Tanrılar tarafından bir anda', 'Yalnız savaşla'], 'Aristoteles\'e göre polis insanın doğal gelişiminin sonucudur: aile, köy, polis. Kent doğa gereği vardır ve insan ancak orada tam yaşar.'),
  ('Aristoteles\'e göre kentin ya da devletin varlık amacı nedir?', 'Yalnız yaşamak değil, iyi yaşamak', ['Yalnız savaş kazanıp topraklarını genişletmek', 'Yalnız ticaret', 'Yalnız vergi toplamak'], 'Aristoteles polisin yalnızca güvenlik ya da ekonomik ihtiyaçlar için değil, erdemli ve mutlu yaşamı mümkün kılmak için bulunduğunu söyler.'),
  ('Aristoteles Dünya\'nın küre biçiminde olduğunu hangi gözleme dayandırır?', 'Ay tutulmasında Dünya\'nın gölgesinin yuvarlak olmasına', ['Yıldızların sabit olması ve gök küresinin her gece aynı biçimde dönmesine', 'Denizin düz olmasına', 'Gündüz ve gecenin eşit olmasına'], 'Aristoteles, Ay tutulması sırasında Dünya\'nın gölgesinin her zaman yuvarlak olmasını Dünya\'nın küre olduğunun kanıtı sayar.'),
  ('Aristoteles\'in mantığında "tümevarım" (epagoge) nedir?', 'Tek tek örneklerden genel bir ilkeye varma', ['Genel bir kuraldan tek tek örneğe inen akıl yürütme türü', 'İki öncülden sonuç çıkarma', 'Kıyas türü'], 'Aristoteles tümevarımı tikellerden tümellere geçiş olarak tanımlar; kıyas ise tümelden tikele ya da iki tümelden sonuca gider.'),
  ('Aristoteles\'in "Analitikler" adlı eserlerinde asıl konu nedir?', 'Kıyas kuramı ve bilimsel kanıtlama', ['Şiir sanatı ve trajedinin öğeleri üzerine inceleme', 'Siyaset kuramı', 'Hayvan sınıflandırması'], 'Birinci Analitikler kıyası, İkinci Analitikler ise bilimsel kanıtlama ve tanımı ele alır.'),
  ('Aristoteles etik terimini hangi sözcükten türetir?', 'Ethos (huy, alışkanlık)', ['Eidos (biçim, görünüş, idea)', 'Epos (destan)', 'Eros (aşk)'], 'Ahlaka dair bilgi "ethika", karakter ve alışkanlık anlamındaki "ethos"tan gelir; erdem alışkanlıkla kazanılır.'),
  ('Epikuros\'un "dört ilaç" (tetrapharmakos) öğüdünde aşağıdakilerden hangisi yer alır?', 'İyi olan kolayca elde edilebilir', ['Tanrılardan her zaman korkmak gerekir', 'Acı sonsuza dek sürer', 'Ölüm acı verici bir sondur'], 'Dört ilaç şudur: tanrıdan korkulmaz, ölümden endişe edilmez, iyi kolay elde edilir, kötü kolay katlanılır. Bunlar kaygıdan kurtulmanın özeti sayılır.'),
  ('Stoacıların dört temel erdemi hangi seçenekte doğru verilmiştir?', 'Bilgelik, adalet, cesaret, ölçülülük', ['İman, umut, sevgi ve ihsan', 'Eros, Philia, Agape, Storge', 'Zenginlik, ün, haz, sağlık'], 'Stoacılar Platon\'dan aldıkları dört temel erdemi bilgelikte birleştirir. Bu erdemler sonradan Hristiyan kardinal erdemlerinin de çerçevesi oldu.'),
  ('Stoacıların "pathe" (tutkular) olarak adlandırdığı dört temel duygu hangisini içerir?', 'Arzu, korku, haz, acı', ['Sevgi, nefret, öfke, şaşkınlık', 'Umut, iman, sabır, bağlılık', 'Gurur, utanç, merhamet, cömertlik'], 'Stoacılara göre tutkular yanlış yargılardan doğar: arzu ve korku gelecekteki iyi ve kötüye, haz ve acı ise şimdiki iyi ve kötüye ilişkin yargılardır.'),
  ('Stoacıların "doğaya uygun yaşa" öğüdündeki doğa neyi içerir?', 'Hem evrenin akıllı düzenini hem insanın akıl sahibi doğasını', ['Yalnız vahşi hayvanların yaşamını', 'Yalnız bitkileri', 'Yalnız bedensel güdüleri'], 'Stoa\'ya göre insan akıl sahibi bir varlıktır; doğaya uygun yaşamak, evrenin logosuyla uyum içinde akla göre yaşamaktır.'),
  ('Milano piskoposu Ambrosius\'un Augustinus üzerindeki etkisi nedir?', 'Vaazlarıyla Augustinus\'u Hristiyanlığa yaklaştırmış, Kutsal Kitabı alegorik yorumlamayı göstermiştir', ['Onu Manihaizm\'e yöneltmiştir', 'Onu Epikurosçu yapmıştır', 'Onu kentten kovmuştur'], 'Augustinus Milano\'da retorik hocalığı yaparken Ambrosius\'un konuşmalarından etkilendi ve onun elinden vaftiz oldu.'),
  ('Aziz Jerome\'un (Hieronymus) Latin Batı için en önemli işi nedir?', 'İncil\'in Latince çevirisi Vulgata\'yı hazırlaması', ['Skolastik yöntemi bulup üniversitelerde ders vermesi, mantık öğretmesi', 'Atomculuğu öğretmesi', 'Üniversite kurması'], 'Jerome\'un Latince İncil çevirisi (Vulgata), Orta Çağ Batısı\'nda yüzyıllarca standart İncil metni oldu.'),
  ('Gazali\'nin "Mi\'yarü\'l-İlm" adlı eseri hangi alana aittir?', 'Mantık', ['Hukuk', 'Astronomi', 'Tıp'], 'Gazali bu kitapta Aristoteles mantığını dinî bilimlere uyarlayarak anlatır; mantığı dine aykırı görmez.'),
  ('Gazali "Tehafüt"te filozofları kaç meselede eleştirmiştir?', 'Yirmi', ['Yüz meselede, bunlardan elliside tekfir', 'Elli', 'Bir'], 'Gazali, filozofların görüşlerini yirmi meselede eleştirdi; bunlardan üçünde onları dinden çıkmış (tekfir) sayarken geri kalanlarında yalnız yanlış buldu.'),
  ('Nizamülmülk\'ün kurduğu Nizamiye medreselerinin düşünce tarihindeki önemi nedir?', 'Selçuklu döneminde devlet destekli sistemli medrese eğitimini yaygınlaştırmaları', ['Üniversitelerin Avrupa\'da kurulmasını sağlamaları', 'Yunan okullarının kapanmasına yol açmaları', 'Bir ordunun kurulması'], 'Nizamiye medreseleri Bağdat\'tan başlayarak Selçuklu coğrafyasında Sünnî eğitimi örgütledi; Gazali de Bağdat Nizamiyesi\'nde ders verdi.'),
  ('Yunus Emre\'nin Türk düşünce tarihinde önemi nedir?', 'Anadolu\'da sade Türkçeyle tasavvufi düşünceyi ve insan sevgisini yaymış olması', ['Latinceyle skolastik eser yazması', 'Mantık kuramı geliştirmesi', 'Rasathane kurması'], 'Yunus Emre 13.-14. yüzyıllarda halk diliyle yazdığı ilahilerde sevgi, hoşgörü ve insana değer verme düşüncesini işlemiştir.'),
  ('Mevlana\'nın "Mesnevi"si hangi dilde yazılmıştır?', 'Farsça', ['Latince', 'Yunanca', 'Türkçe'], 'Mevlana Mesnevi\'yi ve Divan-ı Kebir\'in büyük bölümünü Farsça yazdı. Eserlerinde Arapça ve Türkçe sözcükler de bulunur.'),
  ('Aşağıdaki filozofların doğum sırası eskiden yeniye doğru hangi seçenekte doğru verilmiştir?', 'Thales, Sokrates, Aristoteles, Epikuros', ['Sokrates, Thales, Epikuros, Aristoteles şeklinde', 'Aristoteles, Thales, Sokrates, Epikuros', 'Epikuros, Aristoteles, Sokrates, Thales'], 'Thales MÖ 6. yüzyılda, Sokrates MÖ 5. yüzyılda, Aristoteles MÖ 4. yüzyılda, Epikuros ise MÖ 4. yüzyılın sonlarında yaşadı.'),
  ('Aşağıdaki eserlerden hangisi Platon\'a ait değildir?', 'Organon', ['Devlet\'in Yunanca adı Politeia olan diyalog', 'Timaios', 'Phaidon'], 'Organon, Aristoteles\'in mantık yapıtlarının topluca adıdır. Şölen, Timaios ve Phaidon Platon\'un diyaloglarıdır.'),
  ('Aristoteles\'in kaleminden çıkmamış, başka bir filozofa ait olan yapıt aşağıdakilerden hangisidir?', 'Yasalar', ['Poetika', 'Politika', 'Metafizik'], 'Yasalar Platon\'un son diyaloğudur. Poetika, Politika ve Metafizik Aristoteles\'in yapıtlarıdır.'),
  ('Aşağıdaki okul-kurucu eşleştirmelerinden hangisi yanlıştır?', 'Lykeion – Platon', ['Akademia – Platon', 'Bahçe – Epikuros', 'Stoa – Zenon'], 'Lykeion\'u Aristoteles kurdu. Akademia Platon\'a, Bahçe Epikuros\'a, Stoa Kitionlu Zenon\'a aittir.'),
  ('Skolastik dönemden önceki, Kilise babalarının Hristiyan öğretisini felsefeyle temellendirdiği döneme ne ad verilir?', 'Patristik dönem', ['Hümanist dönem', 'Rönesans dönemi', 'Aydınlanma dönemi'], 'Patristik "baba" anlamındaki Latince "pater"den gelir; Augustinus bu dönemin en önemli düşünürüdür. Sonrası Skolastik dönemdir.'),
  ('Hippokrates\'in tıp anlayışında "dört vücut sıvısı" hangi seçenekte doğru verilmiştir?', 'Kan, balgam, sarı safra, kara safra', ['Su, ateş, hava ve toprak olmak üzere dört temel öğe', 'Ruh, beden, akıl, istek', 'Sıcak, soğuk, ıslak, kuru'], 'Hippokratesçi hekimlik hastalığı doğal nedenlere bağlar ve bu dört sıvının dengesizliğini hastalık nedeni sayar. Bu anlayış yüzyıllarca tıpta etkili oldu.'),
  ('Roma İmparatorluğu\'nda Hristiyanlığın yasallaşmasında dönüm noktası olan 313 tarihli belge hangisidir?', 'Milano Fermanı', ['İznik Konsili kararnamesi', 'Magna Carta', 'Edict of Worms'], 'Konstantin ve Licinius\'un yayımladığı Milano Fermanı, Hristiyanlara dinsel hoşgörü tanıdı. Sonraki dönemde Hristiyan felsefe de gelişmeye başladı.'),
  ('Buda\'nın aydınlanmaya eriştiği anlatılan yer ve koşul hangisidir?', 'Bodh Gaya\'da bir incir (bodhi) ağacının altında meditasyon yaparken', ['Bir savaş alanında', 'Bir sarayda taht üzerinde', 'Bir deniz kıyısında yelken açarken'], 'Gautama, altı yıl süren arayıştan sonra bodhi ağacı altında oturup aydınlanmaya eriştiğini, sonra ilk vaazını Sarnath\'ta verdiğini anlatan kaynaklar vardır.'),
  ('Orta Çağ Avrupası\'nda matbaa öncesi bilgi aktarımında hangi kurumlar önemli rol oynamıştır?', 'Manastırlar ve katedral okulları', ['Gazeteler ve resmî bültenler, haber merkezleri', 'Radyo istasyonları', 'Ticaret fuarları'], 'Yazma eserler manastır skriptoryumlarında çoğaltılır; sonra katedral okulları ve üniversiteler eğitim merkezi oldu.'),
  ('Orta Çağ\'da "skriptoryum" nedir?', 'Manastırlarda el yazması kitapların çoğaltıldığı atölye', ['Askerî eğitim okulu, savaş sanatlarının öğretildiği kışla', 'Bir tiyatro binası', 'Bir hastane'], 'Skriptoryumlarda keşişler kitapları elle kopyalayarak antik ve Hristiyan yazınının korunmasına katkıda bulundu.'),
  ('Platon "Phaidon"da ölümü neye benzetir?', 'Ruhun bedenden ayrılması', ['Ruhun yok olması, hiçliğe karışması', 'Uzun bir uyku', 'Tanrıların cezası'], 'Phaidon\'da felsefe ölüme hazırlık sayılır; ölüm ruhun bedenden ayrılması olarak tanımlanır ve filozof bu ayrılığa yaşamı boyunca hazırlanır.'),
  ('Platon\'un "Devlet" diyaloğunun Yunanca özgün adı olan "Politeia" hangi anlama gelir?', 'Devlet düzeni, anayasa', ['Adalet ve doğruluk kavramı', 'Savaş', 'Güzellik'], 'Politeia, kentin yurttaşlık ve yönetim düzenini anlatır; eserin Türkçedeki adı "Devlet", İngilizcedeki adı "Republic" ise bu terimin çevirileridir.'),
  ('Platon\'un "Yasalar" diyaloğunda Sokrates\'in yerine baş konuşmacı olarak kim bulunur?', 'Atinalı Yabancı', ['Eleli Yabancı, Sofist diyalogundan', 'Timaios', 'Kallikles'], '"Yasalar"da Sokrates yoktur; yaşlı Atinalı bir yabancı, bir Girit\'li ve bir Spartalı ile birlikte ideal kent için yasaları tartışır.'),
  ('Antik anlatıya göre Akademia\'nın girişinde yazılı olduğu söylenen uyarı hangisidir?', 'Geometri bilmeyen buraya girmesin', ['Bilgi güçtür, bu yüzden herkes okusun', 'Kendini bil', 'Hiçbir şey bilmediğimi biliyorum'], 'Geleneğe göre Platon\'un okulunun kapısındaki bu söz, matematiğe verilen önemi gösterir. Kesin bir kaynakla doğrulanmasa da yaygın biçimde anılır.'),
  ('Aristoteles\'in insan tanımı olan "zoon logon ekhon" ifadesi neyi anlatır?', 'Akıl ve söz sahibi canlı', ['Siyasal canlı, yani politik varlık', 'Çalışan canlı', 'Gülen canlı'], 'Aristoteles insanı hayvanlar arasında akıl ve söz sahibi olmasıyla ayırır. Bu, onun etik ve siyaset anlayışının temelidir.'),
  ('Thomas Aquinas\'ın Latin Kilisesi\'ndeki unvanı hangisidir?', 'Melek Doktor', ['Evrensel Doktor, tüm bilimlerin ustası', 'İnce Doktor', 'Harika Doktor'], 'Aquinas "Melek Doktor" diye anılır. Albertus Magnus "Evrensel Doktor", Duns Scotus "İnce Doktor", Roger Bacon "Harika Doktor" unvanıyla bilinir.'),
  ('Epikurosçuluğun Roma\'daki en ünlü savunucusu hangi şairdir?', 'Lucretius', ['Vergilius', 'Horatius', 'Ovidius'], 'Lucretius\'un şiiri Epikurosçu atomculuğu ve haz anlayışını Latince dizelerle anlatır.'),
  ('Geleneksel "Yedi Bilge" listesinde Miletli Thales ile birlikte hangi Atinalı yasa koyucu yer alır?', 'Solon', ['Lykurgos', 'Kleisthenes', 'Perikles'], 'Yedi Bilge, MÖ 7.-6. yüzyılda yaşamış bilge kişilerdir. Solon Atina\'da yasa ve ekonomik reformlar yapmıştır.'),
  ('Epikuros\'un doğduğu yer olarak anılan ada hangisidir?', 'Samos', ['Sicilya', 'Rodos', 'Girit'], 'Epikuros, Atina\'lı bir ailenin çocuğu olarak Samos\'ta doğdu ve Atina\'da Bahçe Okulu\'nu kurdu.'),
  ('Farabi\'nin Bağdat\'tan ayrıldıktan sonra yaşadığı ve saray himayesi gördüğü şehir hangisidir?', 'Halep', ['Kordoba', 'Kahire', 'Buhara'], 'Farabi, Bağdat\'tan sonra Hamdani hükümdarı Seyfüddevle\'nin Halep sarayında bulundu ve Şam yolunda öldü.'),
  ('Gazali\'nin doğduğu yer ve bölge hangisidir?', 'Tus (Horasan)', ['Bağdat (Abbasi başkenti)', 'Şam', 'Kahire'], 'Gazali Horasan\'ın Tus şehrinde doğdu, Nişabur\'da öğrenim gördü, Bağdat\'ta ders verdi ve doğduğu yerde öldü.'),
  ('Platon\'un "Kharmides" diyaloğunda tartışılan erdem hangisidir?', 'Ölçülülük (sophrosyne)', ['Cesaret (savaşçı erdemi)', 'Adalet', 'Cömertlik'], 'Kharmides\'te genç Kharmides ve Kritias ile Sokrates ölçülülüğün ne olduğunu araştırır ve tanım bulunamaz.'),
  ('Platon\'un "Lysis" diyaloğunda hangi konu işlenir?', 'Dostluk', ['Savaş stratejisi ve generalliği', 'Retorik', 'Sanat'], 'Lysis\'te Sokrates gençlerle dostluğun ne olduğunu, neden doğduğunu tartışır; diyalog açık uçlu biter.'),
  ('Platon\'un "Euthydemos" diyaloğu hangi konuyu eleştirir?', 'Eristik söz oyunlarını', ['Tanrıların sayısı sorununu, çokluğu', 'Devlet yönetimini', 'Matematik öğretimini'], 'Euthydemos\'ta iki sofist kardeş, ardı ardına saçma çıkarımlarla karşısındakini şaşırtır; Sokrates bunu gerçek felsefeden ayırır.'),
  ('Platon\'un "Parmenides" diyaloğunun ilk bölümünde ele alınan konu nedir?', 'İdealar kuramına yöneltilen itirazlar', ['Atlantis efsanesi ve eski Atina\'nın savaşları anlatısı', 'Ruhun üç parçası', 'Devletin kuruluşu'], 'Genç Sokrates\'in idealar kuramı yaşlı Parmenides\'ce sorgulanır; "üçüncü adam" ve "katılım" sorunu dile getirilir.'),
  ('Aristoteles\'in öğrencilerinden biri olan Dikaiarkhos hangi alanda anılır?', 'Coğrafya, tarih ve siyaset yazıları', ['Atomculuk ve Demokritos\'un görüşlerinin yorumu', 'Mantık kuramı', 'Tıp'], 'Dikaiarkhos Lykeion\'da yetişen ve coğrafyaya ilişkin eserler yazan bir peripatetik düşünürdür.'),
  ('Antik felsefede "peripatetik" terimi hangi okula ait filozoflar için kullanılır?', 'Aristoteles\'in Lykeion\'u', ['Platon\'un Akademia\'sı, bahçe okulu', 'Epikuros\'un Bahçesi', 'Zenon\'un Stoası'], 'Peripatetik, "dolaşarak ders veren" anlamında Aristoteles ve öğrencilerinin okulunu anar.'),
];
